            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "In their last ditch, the royalists object that this all too bloodless and practical; that people need and want the element of magic and fantasy.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "Is this an argument for abolition? Of course it is. But not for an abolition by fiat: for yet another political change that would come as a surprise to the passively governed.", Author = "Christopher Hitchens" },
