            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "We have preachers and savants who dilate endlessly on the sanctity of family and childhood but who tolerate a system in which a casual observer can correlate a child's social origin with its physical well-being.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "It was an axiom of 'containment' that no part of the known world could be considered neutral.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "There is a limit to the success of conservative populism and the exploitation of 'little guy' or 'silent majority' rhetoric, and it is very often reached because of the emaciated, corrupted personalities of the demagogues themselves.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "Every campaign, Garry Wills once wrote, 'taught Nixon the same lesson: mobilize resentment against those in power.'", Author = "Christopher Hitchens" },
