            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "The disquieting thing about newscaster-babble or editorial-speak is its ready availability as a serf idiom, a vernacular of deference.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "What a country, and what a culture, when the liberals cry before they are hurt, and the reactionaries pose as brave nonconformists, while the radicals make a fetish of their own jokey irrelevance.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "It is not enough to 'have' free speech. People must learn to speak freely.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "But the real bridle on our tongues is imposed by the everyday lying and jargon, sanctioned and promulgated at the highest levels of media and politics, and not by the awkward handful who imagine themselves revolutionaries.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "If a great city or a great state should fall as the result of an apparent 'accident', the there would be a general reason why it required only an accident to make it fall.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "There is a reason for the affected profession of 'anarchist' sympathies among Tories and grandees, and of 'libertarian' principles by Hobbesian yahoos of the right.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "All of them seemed to regard the affair as some sort of heavenly revenge for the sin of radical promiscuity; much as they have represented the AIDS crisis as a vengeance as on sixties morality.", Author = "Christopher Hitchens" },
