            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "'Peace through Strength,' surely history's most exploded nostrum.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "The United States has an isolationist and insular culture, combined with a global and interventionist posture.", Author = "Christopher Hitchens" },
