            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "George W. Bush is lucky to be governor of Texas. He is unusually incurious, abnormally unintelligent, amazingly inarticulate, fantastically uncultured, extraordinarily uneducated, and apparently quite proud of all these things.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "Donald Trump – a ludicrous figure, but at least he’s lived it up a bit in the real world and at least he’s worked out how to cover 90 per cent of his skull with 30 per cent of his hair.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "We don't have to begin by proving that our institutions and our beliefs are human, as all human institutions are; that we are only mammals, as his holiness the Pope is only a mammal.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "We say that we face the heavens, and we find them empty; and that some of us, at any rate, are not alarmed to find this emptiness; and would be more alarmed to find the heavens full of permanent supervision and invigilation; and that an ethical life may be led by someone with no supernatural means of support, without the fear, if it is a fear, or the hope, if it is a hope, of celestial invigilation.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "America is actually the country to which people came in the most of a hurry, to try and find if that life could really be lived as a society.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "And that's why I think modern America should be a lot more anti-religious than it is.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "There is more to inspire awe in one page of Stephen Hawking, than in any of the fantasies of Tertullian, imagining that he could go to the window of heaven, when he was promoted there, and look down, for his consolation, on the torments of the damned.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "The Catholic Church claims to hold the keys of Peter.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "These are large claims for a human, and fallible, and political, and bureaucratic institution to be making for itself in the age of Hawking.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "America is preeminently a country of, if not sexual licenses... a country of sexual tolerance, a country of sexual, I... would settle for pluralism, for now.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "And there will always seem, to some people, I think, something absurd in the enforcement of such statutes, especially since we know most Catholics don't observe them, by a celibate oligarchy and hierarchy.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "Isn't it said, and should it not be believed, or at least affirmed, or at any rate not repudiated, that you should expect to suffer for this; that you should expect to be reviled; that you should be proud to be abused; that you will be told that what you believe is absurd; that you should be glad to hear it, for His sake; that those who despitefully use you is to be expected.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "But instead what do we get? An endless whine of self-pity, of 'Well why are they picking on us.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "The truth of matter is, ladies and gentlemen, comrades and friends, brothers and sisters, religion has it very much its own way in this country of ours.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "It's in the pledge of allegiance, thanks to a stupid intervention of President Eisenhower; it's on the money, it's in the opening of Congress every day, it's at the National Prayer Breakfast.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "It's high time that that situation was reversed and we developed a proper immunity to it, and made sure that religion can only be self-inflicted.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "Intellectuals never sound more foolish than when posing as the last civilised man.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "The secular state is the guarantee of religious pluralism.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "All the excitements of a prohibited book had their usual effect, one of which, as always, is to expose the fact that the censors don't know what they are talking about.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "That phrase, 'loss of innocence,' has become stale with overuse and diminishing returns; no other culture is so addicted to this narcissistic impression of itself as having any innocence to lose in the first place.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "I forget who it was who said that generation -- age group, in other words -- is the most debased form of solidarity.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "I realized that if the battle went on until the last day of my life, I would never get bored in prosecuting it to the utmost.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "Their mantra was: 'Afghanistan, where the world's richest country rains bombs on the world's poorest country.'", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "What about, 'Afghanistan, where the world's most open society confronts the world's most closed one'?", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "'Where American women pilots kill the men who enslave women.'", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "'Where the world's most indiscriminate bombers are bombed by the world's most accurate ones.'", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "'Where the largest number of poor people applaud the bombing of their own regime.'", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "'Bombing Afghanistan back into the Stone Age' was quite a favourite headline for some wobbly liberals...", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "But an instant's thought shows that Afghanistan is being, if anything, bombed OUT of the Stone Age.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "No possible future government in Kabul can be worse than the Taliban, and no thinkable future government would allow the level of Al Qaeda gangsterism to recur.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "The essence of the independent mind lies not in what it thinks, but in how it thinks.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "I check every day to make sure that the bright, smug, pompous, idiotic claim is still there. Then I check to make sure that it still irritates me.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "If I can still exclaim, under my breath, why do they insult me and what do they take me for and what the hell is it supposed to mean unless it's as obviously complacent and conceited and censorious as it seems to be, then at least I know I still have a pulse.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "I therefore have no choice but to find something suspect even in the humblest believer.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "They proclaim us, in Fulke Greville's unforgettable line, 'Created sick — Commanded to be well.'", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "And there are totalitarian insinuations to back this up if its appeal should fail.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "I didn't ask for it, and would willingly have foregone it, but there it is: I'm claimed and saved whether I wish it or not.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "And if I refuse the unsolicited gift? Well, there are still some vague mutterings about an eternity of torment for my ingratitude.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "That is somewhat worse than a Big Brother state, because there could be no hope of its eventually passing away.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "In any case, I find something repulsive about the idea of vicarious redemption.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "I would not throw my numberless sins onto a scapegoat and expect them to pass from me; we rightly sneer at the barbaric societies that practice this unpleasantness in its literal form.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "There's no moral value in the vicarious gesture anyway.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "But you may not assume his actual crimes as if they were your own; for one thing you did not commit them and might have died rather than do so; for another this impossible action would rob him of individual responsibility.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "So the whole apparatus of absolution and forgiveness strikes me as positively immoral, while the concept of revealed truth degrades the concept of free intelligence by purportedly relieving us of the hard task of working out the ethical principles for ourselves.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "You can see the same immorality or amorality in the Christian view of guilt and punishment.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "The Old Testament injunction is the one to exact an eye for an eye and a tooth for a tooth.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "The second is from the Gospels and says that only those without sin should cast the first stone.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "The first is a moral basis for capital punishment and other barbarities; the second is so relativistic and 'nonjudgmental' that it would not allow the prosecution of Charles Manson.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "Our few notions of justice have had to evolve despite these absurd codes of ultra vindictiveness and ultracompassion.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "Judaism has some advantages over Christianity in that, for example, it does not proselytise — except among Jews — and it does not make the cretinous mistake of saying that the Messiah has already made his appearance.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "I think that the indispensable condition of any intellectual liberty is the realisation that there is no such thing.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "Time spent arguing with the faithful is, oddly enough, almost never wasted.", Author = "Christopher Hitchens" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Hitchens", Text = "Only a humorless tyrant could want a perpetual chanting of praises that, one has no choice but to assume, would be the innate virtues and splendors furnished him by his creator, infinite regression, drowned in praise!", Author = "Christopher Hitchens" },
